"""tessaro_feeds - Vendor feed certificate pinning utilities."""

import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Compute the SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Stores and validates pinned certificate fingerprints per host."""

    def __init__(self, pins: dict[str, str]):
        self._pins = pins

    @classmethod
    def load(cls) -> "PinStore":
        """Load the pin store from the default configuration.

        Returns a PinStore with the known vendor feed certificate pins.
        """
        # Default pins for known vendor feeds
        pins = {
            "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
        }
        return cls(pins)

    def matches(self, host: str, fp: str) -> bool:
        """Check if the given fingerprint matches the pinned value for the host."""
        expected = self._pins.get(host)
        if expected is None:
            return False
        return expected == fp
